from pathlib import Path
import random
import re
p=Path('public/assets')
def save(name, body, view='0 0 400 240'):
    body=re.sub(r'<style>.*?</style>', '', body)
    (p/name).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view}">{body}</svg>',encoding='utf-8')
save('fish.svg', '''<defs><linearGradient id="body" x2="0.2" y2="1"><stop stop-color="#173e50"/><stop offset=".35" stop-color="#8daeb6"/><stop offset=".7" stop-color="#e9f4ee"/><stop offset="1" stop-color="#588b9d"/></linearGradient><linearGradient id="fin" x2="1" y2="1"><stop stop-color="#163f56"/><stop offset="1" stop-color="#7cabb8"/></linearGradient><pattern id="scales" width="15" height="12" patternUnits="userSpaceOnUse"><path d="M0 0Q7 15 15 0M-7 6Q0 21 7 6M8 6Q15 21 22 6" fill="none" stroke="#315e6f" stroke-opacity=".24" stroke-width="1"/></pattern></defs><style>.tail{transform-origin:290px 125px;animation:tail 1s ease-in-out infinite}.fin{transform-origin:190px 145px;animation:fin 1.6s ease-in-out infinite}@keyframes tail{50%{transform:scaleX(.72) skewY(6deg)}}@keyframes fin{50%{transform:rotate(12deg)}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}</style><g class="tail"><path d="M279 124Q320 100 359 68L343 123 364 177Q311 153 279 137" fill="url(#fin)" stroke="#214d60" stroke-width="2"/><path d="M305 124L350 86M309 131L350 163M310 128L341 125" stroke="#b3d2d8" fill="none" opacity=".65"/></g><path d="M134 89L160 45 179 57 192 43 208 60 221 56 241 86" fill="url(#fin)" stroke="#355f71" stroke-width="2"/><path d="M171 163L214 199 248 172" fill="url(#fin)"/><path d="M45 124Q80 74 163 78Q240 67 302 126Q255 176 167 174Q81 175 45 131L34 128Z" fill="url(#body)" stroke="#234f60" stroke-width="2"/><path d="M114 90Q213 68 288 126Q228 172 119 164" fill="url(#scales)"/><path d="M109 91Q143 121 112 161" fill="none" stroke="#335969" stroke-width="3"/><path d="M117 102Q135 127 115 150" fill="none" stroke="#d5e7e7" stroke-width="2"/><path class="fin" d="M153 133Q185 123 218 149L184 165Z" fill="url(#fin)" stroke="#466c78"/><circle cx="81" cy="113" r="13" fill="#c5ab5b"/><circle cx="81" cy="113" r="8" fill="#101f29"/><circle cx="78" cy="110" r="3" fill="white"/><path d="M42 128L68 130" stroke="#284b5b" stroke-width="2"/><path d="M137 92Q202 77 250 108" stroke="white" stroke-opacity=".45" stroke-width="3" fill="none"/>''')
save('prawn.svg','''<defs><linearGradient id="shell" x2=".2" y2="1"><stop stop-color="#f3dc87"/><stop offset=".45" stop-color="#b19434"/><stop offset="1" stop-color="#5a602d"/></linearGradient></defs><style>.legs{transform-origin:200px 140px;animation:kick 2s ease-in-out infinite}.feelers{transform-origin:130px 90px;animation:feel 3s ease-in-out infinite}@keyframes kick{50%{transform:skewX(8deg)}}@keyframes feel{50%{transform:rotate(-3deg)}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}</style><g class="feelers" fill="none" stroke="#9d7b2c" stroke-width="2"><path d="M137 105Q75 15 23 55Q-9 97 115 98M132 98Q40 1 24 43Q16 69 128 90M128 96Q68 73 8 110"/></g><g class="legs" stroke="#9a7a2e" stroke-width="3" fill="none"><path d="M141 129L113 163 68 186M161 136L145 172 110 194M180 141L169 181 135 203M201 145L207 184 180 212M224 147L243 182 224 204M248 146L276 178 266 198"/></g><path d="M101 92Q148 64 218 86Q282 99 309 144Q323 162 319 182L292 172Q272 131 217 130L147 129Z" fill="url(#shell)" stroke="#6f682d" stroke-width="2"/><path d="M174 81Q190 99 182 134M203 83Q222 102 213 134M233 92Q249 111 243 138M259 103Q276 124 273 150M285 122Q300 141 299 168" fill="none" stroke="#625b28" stroke-width="4"/><path d="M314 168L348 189 329 214 317 190 301 210 294 180Z" fill="url(#shell)" stroke="#6f682d" stroke-width="2"/><path d="M102 93L71 88 97 109 130 127" fill="url(#shell)" stroke="#6f682d" stroke-width="2"/><circle cx="117" cy="91" r="6" fill="#122a28"/><circle cx="115" cy="89" r="2" fill="white"/><path d="M143 92Q209 73 270 120" stroke="#fff1bd" stroke-width="4" fill="none" opacity=".6"/>''')
random.seed(31)
for mode in ['floating','sinking','mash']:
    bg='<defs><radialGradient id="water"><stop stop-color="#4d8c95"/><stop offset="1" stop-color="#133d4c"/></radialGradient><linearGradient id="pellet" x2=".4" y2="1"><stop stop-color="#e0b16d"/><stop offset=".5" stop-color="#966338"/><stop offset="1" stop-color="#4e321f"/></linearGradient></defs>'
    bg+='<rect width="400" height="400" fill="url(#water)"/>' if mode=='floating' else '<rect width="400" height="400" fill="#442f1d"/>'
    for i in range(70 if mode=='floating' else 600):
        x,y=random.randint(0,400),random.randint(0,400)
        if mode=='floating': bg+=f'<ellipse cx="{x}" cy="{y+9}" rx="20" ry="5" fill="none" stroke="#9ad1d0" opacity=".18"/>'
        rx=random.randint(6,12) if mode=='floating' else random.randint(3,6)
        bg+=f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{rx*.7}" fill="url(#pellet)" transform="rotate({random.randint(-40,40)} {x} {y})"/>'
    if mode=='mash':
        bg+='<path d="M50 370Q30 160 90 65Q200 19 309 71Q372 189 350 370Z" fill="#b79665"/><path d="M90 65Q186 125 309 71L280 198 121 200Z" fill="#5a3d23"/><ellipse cx="199" cy="199" rx="84" ry="34" fill="#b78b50"/><path d="M50 370L90 65M350 370L309 71" stroke="#dfc393" stroke-width="10"/>'
        for i in range(240):
            x,y=random.randint(105,290),random.randint(175,215);bg+=f'<circle cx="{x}" cy="{y}" r="2" fill="{random.choice(["#d0ab6e","#956735","#b98a48"])}"/>'
    save(f'{mode}-feed.svg',bg,'0 0 400 400')
